algorithms.pseudocode:
if InFlightQueue.is_empty():
    return
inflight = InFlightQueue.pop_oldest()
if not inflight.valid:
    return

entry = WPT[inflight.wpt_idx]
idx = inflight.counter_idx
wormhole_pred = inflight.wormhole_pred

if branch_outcome == TAKEN:
    entry.counters[idx] = min(entry.counters[idx] + 1, (1 << (counter_bits - 1)) - 1)
else:
    entry.counters[idx] = max(entry.counters[idx] - 1, -(1 << (counter_bits - 1)))

if wormhole_pred != TAGE_prediction:
    if wormhole_pred == branch_outcome:
        entry.conf = min(entry.conf + 1, (1 << conf_bits) - 1)
    else:
        entry.conf = max(entry.conf - 1, 0)

entry.history = ((entry.history << 1) | branch_outcome) & ((1 << history_bits) - 1)

if LPT_TOTAL > 0:
    branch_tag = branch_PC & ((1 << tag_bits) - 1)
    match = -1
    for i in range(wpt_entries):
        if WPT[i].tag == branch_tag:
            match = i
            break
    if match != -1:
        WPT[match].ranking = min(WPT[match].ranking + 1, (1 << ranking_bits) - 1)
    else:
        replace_idx = 0
        lowest_rank = WPT[0].ranking
        for i in range(1, wpt_entries):
            if WPT[i].ranking < lowest_rank:
                lowest_rank = WPT[i].ranking
                replace_idx = i
        WPT[replace_idx].tag = branch_tag
        WPT[replace_idx].conf = 0
        WPT[replace_idx].ranking = initial_ranking
        WPT[replace_idx].length = LPT_TOTAL & ((1 << length_bits) - 1)
        WPT[replace_idx].history = 0
        for i in range(num_counters):
            WPT[replace_idx].counters[i] = 0

for inflight in reversed(InFlightQueue.elements()):
    if inflight.instruction_age > squash_point:
        InFlightQueue.remove(inflight)
    else:
        break
